**Indexes** are data structures that improve query speed by allowing fast data lookup, similar to a book's index. They trade storage space for read performance.

```sql
-- ===== CREATING INDEXES =====

-- Single-column index
CREATE INDEX idx_users_email ON users(email);

-- Composite index (multiple columns)
CREATE INDEX idx_orders_user_date ON orders(customer_id, order_date);

-- Unique index (prevents duplicates)
CREATE UNIQUE INDEX idx_users_email_unique ON users(email);

-- Full-text index (text search)
CREATE FULLTEXT INDEX idx_articles_content ON articles(title, body);

-- Partial index (only specific rows)
CREATE INDEX idx_active_users ON users(email) WHERE status = 'active';

-- Descending index
CREATE INDEX idx_products_price_desc ON products(price DESC);

-- Dropping indexes
DROP INDEX idx_users_email ON users;

-- ===== ANALYZING QUERY PERFORMANCE =====

-- EXPLAIN to see query plan (MySQL)
EXPLAIN SELECT * FROM users WHERE email = 'john@example.com';

-- EXPLAIN ANALYZE (PostgreSQL) - shows actual execution time
EXPLAIN ANALYZE SELECT * FROM orders WHERE customer_id = 123;

-- ===== WHEN INDEXES HELP =====

-- GOOD: Index on email speeds up WHERE
SELECT * FROM users WHERE email = 'john@example.com';

-- GOOD: Index on (last_name, first_name) helps
SELECT * FROM users WHERE last_name = 'Smith' AND first_name = 'John';

-- GOOD: Index on order_date for range query
SELECT * FROM orders WHERE order_date BETWEEN '2024-01-01' AND '2024-12-31';

-- GOOD: Index on foreign key for JOIN
SELECT * FROM orders o JOIN customers c ON o.customer_id = c.id;

-- GOOD: Index for ORDER BY (avoids filesort)
SELECT * FROM products ORDER BY price DESC;

-- GOOD: Covering index (all needed columns in index)
CREATE INDEX idx_users_covering ON users(email, name, status);
SELECT email, name FROM users WHERE email = 'test@test.com';

-- ===== WHEN INDEXES DON'T HELP =====

-- BAD: Function call prevents index use
SELECT * FROM users WHERE UPPER(email) = 'JOHN@EXAMPLE.COM';
-- Fix: Create functional index
CREATE INDEX idx_users_email_upper ON users(UPPER(email));

-- BAD: Leading wildcard in LIKE
SELECT * FROM users WHERE name LIKE '%Smith%';
-- Good: Trailing wildcard uses index
SELECT * FROM users WHERE name LIKE 'Smith%';

-- BAD: OR condition with different columns
SELECT * FROM users WHERE email = 'a@b.com' OR phone = '555-1234';

-- BAD: Not using leftmost column in composite index
-- Index on (last_name, first_name, age)
SELECT * FROM users WHERE first_name = 'John';  -- Won't use index
SELECT * FROM users WHERE last_name = 'Smith';  -- Will use index

-- BAD: Small table (full scan is faster)
SELECT * FROM small_table WHERE status = 'active';

-- ===== INDEX TYPES BY DATABASE =====

-- MySQL
CREATE INDEX idx_name ON table(column);
CREATE FULLTEXT INDEX idx_fulltext ON articles(content);

-- PostgreSQL
CREATE INDEX idx_gin ON documents USING GIN (data);
CREATE INDEX idx_btree ON users USING BTREE (email);
CREATE INDEX idx_hash ON cache USING HASH (key);

-- SQL Server
CREATE CLUSTERED INDEX idx_clustered ON orders(order_date);
CREATE NONCLUSTERED INDEX idx_nonclustered ON customers(name);

-- ===== INDEX MAINTENANCE =====

-- See existing indexes (MySQL)
SHOW INDEX FROM users;

-- Rebuild index (MySQL)
ALTER TABLE users DROP INDEX idx_email;
ALTER TABLE users ADD INDEX idx_email(email);

-- Analyze table to update index statistics
ANALYZE TABLE users;

-- ===== PRACTICAL EXAMPLE: Optimizing Slow Query =====

-- Slow query (no index)
SELECT customer_id, SUM(total) 
FROM orders 
WHERE order_date >= '2024-01-01'
GROUP BY customer_id;

-- Add indexes to optimize
CREATE INDEX idx_orders_date ON orders(order_date);
CREATE INDEX idx_orders_customer_date ON orders(customer_id, order_date);

-- Now the query uses covering index
SELECT customer_id, SUM(total) 
FROM orders 
WHERE order_date >= '2024-01-01'
GROUP BY customer_id;

-- ===== MONITORING INDEX USAGE =====

-- Find unused indexes (MySQL)
SELECT * FROM sys.schema_unused_indexes;

-- Index hit rate (PostgreSQL)
SELECT schemaname, tablename, indexname, idx_scan, idx_tup_read
FROM pg_stat_user_indexes;
```

**Index Type Comparison:**

| Index Type | Best For | Trade-offs |
|------------|----------|------------|
| B-Tree | Equality and range queries | Default, good all-around |
| Hash | Exact equality (no range) | Very fast lookups, no sorting |
| Bitmap | Low cardinality columns (status, gender) | Compact, good for AND/OR |
| Full-text | Text search | Search within text |
| Spatial | Geographic data (coordinates, shapes) | GIS queries |
| GIN (PostgreSQL) | Arrays, JSON, full-text | Complex data types |

**Best Practices:**
1. Index columns used in WHERE, JOIN, ORDER BY, GROUP BY
2. Create composite indexes in order of selectivity (most unique first)
3. Avoid over-indexing (each index slows INSERT/UPDATE/DELETE)
4. Remove unused indexes
5. Consider index size vs performance gain
6. Use covering indexes for frequent queries
7. Monitor and rebuild fragmented indexes periodically

**MongoDB** is a document-oriented NoSQL database that stores data in flexible, JSON-like documents (BSON). It's schema-less and scales horizontally.

```javascript
// ===== CONNECTION AND DATABASE =====
// mongosh (MongoDB Shell)
use mydb;

// ===== CREATE (Insert) Operations =====

// Insert one document
db.users.insertOne({
    name: "John Doe",
    email: "john@example.com",
    age: 30,
    address: {
        street: "123 Main St",
        city: "Boston",
        zip: "02101"
    },
    hobbies: ["reading", "coding", "hiking"],
    created_at: new Date()
});

// Insert multiple documents
db.products.insertMany([
    { name: "Laptop", price: 999.99, category: "Electronics", stock: 10 },
    { name: "Mouse", price: 29.99, category: "Electronics", stock: 50 },
    { name: "Desk", price: 249.99, category: "Furniture", stock: 5 },
    { name: "Chair", price: 199.99, category: "Furniture", stock: 8 }
]);

// ===== READ (Find) Operations =====

// Find all
db.users.find();

// Find with filter
db.users.find({ age: { $gt: 25 } });
db.products.find({ category: "Electronics", price: { $lt: 500 } });

// Find one
db.users.findOne({ email: "john@example.com" });

// Projection (select specific fields)
db.users.find({}, { name: 1, email: 1, _id: 0 });

// Query operators
db.products.find({
    price: { $gte: 50, $lte: 500 },
    category: { $in: ["Electronics", "Furniture"] }
});

db.users.find({
    $or: [
        { age: { $lt: 18 } },
        { age: { $gt: 65 } }
    ]
});

// Array queries
db.users.find({ hobbies: "coding" });  // contains
db.users.find({ hobbies: { $all: ["coding", "reading"] } });
db.users.find({ hobbies: { $size: 3 } });

// Nested field queries
db.users.find({ "address.city": "Boston" });

// Regex search
db.users.find({ name: { $regex: /^John/, $options: "i" } });

// Sorting, limiting, skipping
db.products.find().sort({ price: -1 }).limit(5).skip(10);

// ===== UPDATE Operations =====

// Update one
db.users.updateOne(
    { email: "john@example.com" },
    { $set: { age: 31, "address.city": "Cambridge" } }
);

// Update many
db.products.updateMany(
    { category: "Electronics" },
    { $mul: { price: 0.9 } }  // 10% discount
);

// Replace document (completely overwrite)
db.users.replaceOne(
    { email: "john@example.com" },
    { name: "John Smith", email: "john@example.com", age: 32 }
);

// Array update operators
db.users.updateOne(
    { email: "john@example.com" },
    { $push: { hobbies: "gaming" } }
);

db.users.updateOne(
    { email: "john@example.com" },
    { $pull: { hobbies: "hiking" } }
);

db.users.updateOne(
    { email: "john@example.com" },
    { $addToSet: { hobbies: "reading" } }  // only if not exists
);

// Increment
db.products.updateOne(
    { name: "Laptop" },
    { $inc: { stock: -1 } }
);

// Upsert (update or insert if not exists)
db.users.updateOne(
    { email: "new@example.com" },
    { $set: { name: "New User", age: 25 } },
    { upsert: true }
);

// ===== DELETE Operations =====

// Delete one
db.users.deleteOne({ email: "old@example.com" });

// Delete many
db.products.deleteMany({ stock: 0 });

// Delete all
db.products.deleteMany({});

// Drop collection
db.orders.drop();

// ===== AGGREGATION PIPELINE =====

// Basic pipeline
db.orders.aggregate([
    { $match: { status: "completed" } },
    { $group: { _id: "$customer_id", totalSpent: { $sum: "$total" } } },
    { $sort: { totalSpent: -1 } },
    { $limit: 10 }
]);

// Complex example with multiple stages
db.orders.aggregate([
    // Stage 1: Filter
    { $match: { order_date: { $gte: ISODate("2024-01-01") } } },

    // Stage 2: Lookup (JOIN)
    { $lookup: {
        from: "customers",
        localField: "customer_id",
        foreignField: "_id",
        as: "customer"
    }},

    // Stage 3: Unwind array
    { $unwind: "$customer" },

    // Stage 4: Group by
    { $group: {
        _id: {
            year: { $year: "$order_date" },
            month: { $month: "$order_date" },
            category: "$category"
        },
        total_revenue: { $sum: "$total" },
        order_count: { $sum: 1 },
        avg_order: { $avg: "$total" }
    }},

    // Stage 5: Project (reshape output)
    { $project: {
        year: "$_id.year",
        month: "$_id.month",
        category: "$_id.category",
        revenue: "$total_revenue",
        orders: "$order_count",
        average: { $round: ["$avg_order", 2] },
        _id: 0
    }},

    // Stage 6: Sort
    { $sort: { year: -1, month: 1, revenue: -1 } }
]);

// Common aggregation operators
db.sales.aggregate([
    { $match: { region: "North" } },
    { $group: {
        _id: "$product",
        total: { $sum: "$amount" },
        count: { $sum: 1 },
        avg: { $avg: "$amount" },
        min: { $min: "$amount" },
        max: { $max: "$amount" },
        values: { $push: "$amount" }
    }},
    { $addFields: {
        rating: {
            $switch: {
                branches: [
                    { case: { $gte: ["$total", 1000] }, then: "Gold" },
                    { case: { $gte: ["$total", 500] }, then: "Silver" }
                ],
                default: "Bronze"
            }
        }
    }}
]);

// ===== INDEXING IN MONGODB =====

// Single field index
db.users.createIndex({ email: 1 });  // 1 = ascending, -1 = descending

// Unique index
db.users.createIndex({ email: 1 }, { unique: true });

// Compound index
db.orders.createIndex({ customer_id: 1, order_date: -1 });

// Text index (search)
db.articles.createIndex({ title: "text", body: "text" });
db.articles.find({ $text: { $search: "mongodb database" } });

// Geospatial index
db.locations.createIndex({ coordinates: "2dsphere" });
db.locations.find({
    coordinates: {
        $near: {
            $geometry: { type: "Point", coordinates: [-73.935, 40.730] },
            $maxDistance: 5000
        }
    }
});

// TTL index (auto-delete after time)
db.sessions.createIndex({ created_at: 1 }, { expireAfterSeconds: 3600 });

// Partial index (only some documents)
db.users.createIndex(
    { email: 1 },
    { partialFilterExpression: { status: "active" } }
);

// Background index (non-blocking)
db.large_collection.createIndex({ field: 1 }, { background: true });

// List indexes
db.users.getIndexes();

// Drop index
db.users.dropIndex("email_1");

// ===== AGGREGATION WITH LOOKUP (JOIN) =====

// Simple lookup
db.orders.aggregate([
    { $lookup: {
        from: "customers",
        localField: "customer_id",
        foreignField: "_id",
        as: "customer_info"
    }}
]);

// Pipeline lookup (complex join)
db.orders.aggregate([
    { $lookup: {
        from: "inventory",
        let: { prod_id: "$product_id" },
        pipeline: [
            { $match: { $expr: { $eq: ["$_id", "$$prod_id"] } } },
            { $project: { name: 1, price: 1, _id: 0 } }
        ],
        as: "product_details"
    }}
]);
```

