**ACID** properties ensure reliable processing of database transactions. They guarantee data integrity even in case of errors, power failures, or concurrent access.

```sql
-- ===== ATOMICITY (All or nothing) =====
-- Transaction either completes fully or has no effect

BEGIN TRANSACTION;
    UPDATE accounts SET balance = balance - 100 WHERE user_id = 1;
    UPDATE accounts SET balance = balance + 100 WHERE user_id = 2;
    -- If any statement fails, entire transaction rolls back
COMMIT;

-- Example of atomicity failure prevention
BEGIN TRANSACTION;
    INSERT INTO orders (user_id, total) VALUES (1, 99.99);
    -- Get the last inserted ID
    DECLARE @order_id INT = SCOPE_IDENTITY();
    INSERT INTO order_items (order_id, product_id, quantity) VALUES (@order_id, 10, 1);
    -- If second INSERT fails, first INSERT is rolled back
COMMIT;

-- With error handling (SQL Server)
BEGIN TRY
    BEGIN TRANSACTION;
        UPDATE inventory SET stock = stock - 1 WHERE product_id = 10;
        INSERT INTO sales (product_id, quantity) VALUES (10, 1);
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    ROLLBACK TRANSACTION;
    THROW;
END CATCH;

-- ===== CONSISTENCY (Data integrity maintained) =====
-- All constraints, rules, triggers are satisfied

-- Schema with constraints for consistency
CREATE TABLE products (
    id INT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    price DECIMAL(10,2) CHECK (price >= 0),  -- prevents negative price
    stock INT DEFAULT 0 CHECK (stock >= 0)    -- prevents negative stock
);

CREATE TABLE orders (
    id INT PRIMARY KEY,
    customer_id INT NOT NULL,
    order_date DATE DEFAULT CURRENT_DATE,
    total DECIMAL(10,2) CHECK (total >= 0)
);

-- Foreign key ensures referential consistency
ALTER TABLE orders ADD CONSTRAINT fk_customer 
    FOREIGN KEY (customer_id) REFERENCES customers(id);

-- Transaction that maintains consistency
BEGIN TRANSACTION;
    -- Check sufficient stock (business rule)
    IF (SELECT stock FROM products WHERE id = 1) >= 5
    BEGIN
        UPDATE products SET stock = stock - 5 WHERE id = 1;
        INSERT INTO orders (customer_id, total) VALUES (100, 49.95);
        COMMIT;
    END
    ELSE
    BEGIN
        ROLLBACK;
        RAISERROR('Insufficient stock', 16, 1);
    END

-- ===== ISOLATION (Concurrent transactions don't interfere) =====
-- Different isolation levels balance consistency vs performance

-- READ UNCOMMITTED (dirty reads possible) - highest performance
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
BEGIN TRANSACTION;
    SELECT * FROM accounts;  -- May see uncommitted changes
COMMIT;

-- READ COMMITTED (default in many DBs) - no dirty reads
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
BEGIN TRANSACTION;
    SELECT * FROM accounts;  -- Only sees committed data
COMMIT;

-- REPEATABLE READ (no non-repeatable reads)
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
BEGIN TRANSACTION;
    SELECT balance FROM accounts WHERE id = 1;  -- Returns same value if queried again
    -- Another transaction cannot modify this row
    SELECT balance FROM accounts WHERE id = 1;  -- Same value guaranteed
COMMIT;

-- SERIALIZABLE (highest isolation, no phantom reads)
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN TRANSACTION;
    SELECT COUNT(*) FROM orders WHERE status = 'pending';
    -- No new pending orders can be inserted
    SELECT COUNT(*) FROM orders WHERE status = 'pending';  -- Same count
COMMIT;

-- Phantom Read Example (Prevented by SERIALIZABLE)
-- Transaction 1
BEGIN TRANSACTION;
    SELECT * FROM products WHERE category = 'Electronics';
    -- Another transaction inserts a new Electronics product
    SELECT * FROM products WHERE category = 'Electronics';  -- Phantom (new row appears)
COMMIT;

-- Lost Update Prevention (Optimistic Locking)
-- Using version column
CREATE TABLE products (
    id INT PRIMARY KEY,
    name VARCHAR(100),
    stock INT,
    version INT DEFAULT 0
);

-- Transaction 1
DECLARE @version INT;
SELECT @version = version FROM products WHERE id = 1;
UPDATE products SET stock = stock - 1, version = version + 1 
WHERE id = 1 AND version = @version;
IF @@ROWCOUNT = 0
    RAISERROR('Conflict, retry', 16, 1);

-- Pessimistic Locking
BEGIN TRANSACTION;
    SELECT * FROM products WITH (UPDLOCK, ROWLOCK) WHERE id = 1;
    -- Lock acquired, other transactions wait
    UPDATE products SET stock = stock - 1 WHERE id = 1;
COMMIT;

-- ===== DURABILITY (Committed changes persist) =====
-- Once transaction commits, data survives crashes

-- Transaction log ensures durability
BEGIN TRANSACTION;
    UPDATE accounts SET balance = 1000 WHERE id = 1;
COMMIT;  -- Written to transaction log before acknowledgment

-- Write-ahead logging (WAL) configuration (PostgreSQL)
-- postgresql.conf
wal_level = replica
fsync = on
synchronous_commit = on
wal_sync_method = fdatasync

-- Delayed durability (MySQL) - trade durability for performance
SET GLOBAL innodb_flush_log_at_trx_commit = 2;  -- flush once per second

-- SQL Server - delayed durability
ALTER DATABASE MyDB SET DELAYED_DURABILITY = FORCED;
BEGIN TRANSACTION WITH DELAYED_DURABILITY;
    UPDATE accounts SET balance = balance - 100 WHERE id = 1;
COMMIT TRANSACTION;  -- May be lost in crash, but faster

-- ===== ISOLATION LEVEL COMPARISON =====

/*
| Level | Dirty Read | Non-Repeatable | Phantom | Performance |
|-------|------------|----------------|---------|-------------|
| READ UNCOMMITTED | Yes | Yes | Yes | Best |
| READ COMMITTED | No | Yes | Yes | Good |
| REPEATABLE READ | No | No | Yes | Medium |
| SERIALIZABLE | No | No | No | Worst |
*/

-- ===== PRACTICAL EXAMPLE: Money Transfer =====

CREATE PROCEDURE TransferMoney(
    @from_account INT,
    @to_account INT,
    @amount DECIMAL(10,2)
)
AS
BEGIN
    SET XACT_ABORT ON;  -- Auto-rollback on error
    BEGIN TRANSACTION;

    BEGIN TRY
        -- Check sufficient balance
        DECLARE @balance DECIMAL(10,2);
        SELECT @balance = balance FROM accounts WHERE id = @from_account;

        IF @balance < @amount
            THROW 50000, 'Insufficient funds', 1;

        -- Withdraw
        UPDATE accounts SET balance = balance - @amount 
        WHERE id = @from_account;

        -- Deposit
        UPDATE accounts SET balance = balance + @amount 
        WHERE id = @to_account;

        -- Record transaction
        INSERT INTO transfers (from_account, to_account, amount, transfer_date)
        VALUES (@from_account, @to_account, @amount, GETDATE());

        COMMIT TRANSACTION;
        PRINT 'Transfer successful';
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;

-- ===== TESTING ISOLATION =====

-- Session 1
BEGIN TRANSACTION;
    UPDATE accounts SET balance = 500 WHERE id = 1;
    WAITFOR DELAY '00:00:10';
COMMIT;

-- Session 2 (runs concurrently)
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
SELECT balance FROM accounts WHERE id = 1;  -- Waits for lock or sees old value
```

**ACID Violations and Prevention:**

| Violation | Description | Prevention |
|-----------|-------------|------------|
| Dirty Read | Read uncommitted data | READ COMMITTED+ |
| Lost Update | Overwrite concurrent update | Locking, versioning |
| Non-repeatable Read | Different values in same tx | REPEATABLE READ |
| Phantom Read | New rows appear | SERIALIZABLE |
| Write Skew | Concurrent updates violate constraint | Serialization |

**Trade-offs:**
- Higher isolation = lower concurrency = slower performance
- BASE (Basically Available, Soft state, Eventual consistency) for distributed systems
- NoSQL databases often sacrifice ACID for scalability (CAP theorem)

A **transaction** is a logical unit of work that contains one or more SQL statements. Transactions ensure data integrity by making a group of operations atomic.

```sql
-- ===== BASIC TRANSACTION CONTROL =====

-- Begin transaction (implicit or explicit)
BEGIN TRANSACTION;
-- or
START TRANSACTION;

-- Commit (save changes permanently)
COMMIT;

-- Rollback (undo changes)
ROLLBACK;

-- ===== SIMPLE TRANSACTION EXAMPLE =====

-- Create sample table
CREATE TABLE bank_accounts (
    id INT PRIMARY KEY,
    name VARCHAR(100),
    balance DECIMAL(10,2) CHECK (balance >= 0)
);

INSERT INTO bank_accounts VALUES (1, 'Alice', 1000), (2, 'Bob', 500);

-- Transaction: Transfer $200 from Alice to Bob
BEGIN TRANSACTION;
    UPDATE bank_accounts SET balance = balance - 200 WHERE id = 1;
    UPDATE bank_accounts SET balance = balance + 200 WHERE id = 2;

    -- Check if any constraint violated
    IF @@ERROR != 0
    BEGIN
        ROLLBACK;
        PRINT 'Transaction failed, rolled back';
    END
    ELSE
    BEGIN
        COMMIT;
        PRINT 'Transaction successful';
    END

-- ===== TRANSACTION WITH ERROR HANDLING (SQL Server) =====

BEGIN TRY
    BEGIN TRANSACTION;
        UPDATE inventory SET stock = stock - 5 WHERE product_id = 100;
        INSERT INTO sales (product_id, quantity, sale_date) 
        VALUES (100, 5, GETDATE());

        -- Simulate error
        IF (SELECT stock FROM inventory WHERE product_id = 100) < 0
            THROW 50000, 'Negative stock!', 1;
    COMMIT TRANSACTION;
    PRINT 'Transaction committed';
END TRY
BEGIN CATCH
    ROLLBACK TRANSACTION;
    PRINT 'Transaction rolled back: ' + ERROR_MESSAGE();
    THROW;
END CATCH

-- ===== TRANSACTION IN MYSQL =====

START TRANSACTION;

UPDATE products SET stock = stock - 1 WHERE id = 1;
UPDATE orders SET status = 'completed' WHERE id = 100;

-- Check for errors
IF (SELECT stock FROM products WHERE id = 1) >= 0 THEN
    COMMIT;
ELSE
    ROLLBACK;
END IF;

-- ===== SAVEPOINTS (Partial rollback) =====

BEGIN TRANSACTION;

INSERT INTO logs (action, timestamp) VALUES ('Start process', NOW());
SAVEPOINT after_log;

UPDATE accounts SET balance = balance - 100 WHERE id = 1;
SAVEPOINT after_withdrawal;

UPDATE accounts SET balance = balance + 100 WHERE id = 2;

-- Something went wrong, rollback to savepoint
ROLLBACK TO SAVEPOINT after_withdrawal;

-- Continue with alternative action
UPDATE accounts SET balance = balance - 50 WHERE id = 1;
UPDATE accounts SET balance = balance + 50 WHERE id = 3;

COMMIT;  -- Commits everything from after_withdrawal to end

-- ===== NESTED TRANSACTIONS (with savepoints) =====

-- PostgreSQL style
BEGIN;
    INSERT INTO audit (action) VALUES ('outer transaction');

    SAVEPOINT inner_tx;
        INSERT INTO audit (action) VALUES ('inner transaction');
        -- If inner fails, rollback to savepoint
    ROLLBACK TO SAVEPOINT inner_tx;

COMMIT;

-- ===== AUTOCOMMIT BEHAVIOR =====

-- Disable autocommit (MySQL)
SET autocommit = 0;

-- Enable autocommit
SET autocommit = 1;

-- Check autocommit status (PostgreSQL)
SHOW autocommit;

-- ===== PRACTICAL EXAMPLES =====

-- 1. Order processing with inventory check
CREATE PROCEDURE ProcessOrder(@order_id INT)
AS
BEGIN
    DECLARE @product_id INT, @quantity INT, @available INT;

    BEGIN TRANSACTION;

    -- Get order details
    SELECT @product_id = product_id, @quantity = quantity
    FROM order_items WHERE order_id = @order_id;

    -- Check inventory
    SELECT @available = stock FROM inventory WHERE product_id = @product_id;

    IF @available >= @quantity
    BEGIN
        UPDATE inventory SET stock = stock - @quantity WHERE product_id = @product_id;
        UPDATE orders SET status = 'processed' WHERE id = @order_id;
        COMMIT;
        PRINT 'Order processed successfully';
    END
    ELSE
    BEGIN
        ROLLBACK;
        PRINT 'Insufficient stock';
    END
END

-- 2. Batch update with transaction (all or nothing)
BEGIN TRANSACTION;

UPDATE employees SET salary = salary * 1.10 WHERE department = 'Sales';
UPDATE employees SET salary = salary * 1.05 WHERE department = 'Engineering';
UPDATE employees SET salary = salary * 1.03 WHERE department = 'Support';

-- Verify no negative salaries
IF EXISTS (SELECT 1 FROM employees WHERE salary < 0)
    ROLLBACK;
ELSE
    COMMIT;

-- 3. Transaction with retry logic (application code)
-- Python example
import psycopg2
from tenacity import retry, stop_after_attempt, wait_exponential

@retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=1, max=10))
def transfer_money(from_id, to_id, amount):
    conn = psycopg2.connect("dbname=test user=postgres")
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("UPDATE accounts SET balance = balance - %s WHERE id = %s", (amount, from_id))
                cur.execute("UPDATE accounts SET balance = balance + %s WHERE id = %s", (amount, to_id))
                # If deadlock, retry automatically
    finally:
        conn.close()

-- 4. Explicit locking within transaction
BEGIN TRANSACTION;

-- Lock rows for update (prevents others from modifying)
SELECT * FROM inventory WITH (UPDLOCK, ROWLOCK)
WHERE product_id IN (1, 2, 3);

-- Now safe to update
UPDATE inventory SET stock = stock - 1 WHERE product_id IN (1, 2, 3);

COMMIT;

-- 5. Transaction isolation level demonstration
-- Session 1
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
BEGIN TRANSACTION;
    SELECT balance FROM accounts WHERE id = 1;  -- Returns 1000
    -- Session 2 cannot modify this row
    SELECT balance FROM accounts WHERE id = 1;  -- Still 1000
COMMIT;

-- Session 2 (runs concurrently)
UPDATE accounts SET balance = 900 WHERE id = 1;  -- Blocks until Session 1 commits

-- ===== MONITORING TRANSACTIONS =====

-- SQL Server - view active transactions
DBCC OPENTRAN;

SELECT * FROM sys.dm_tran_active_transactions;
SELECT * FROM sys.dm_tran_session_transactions;

-- PostgreSQL - view locks
SELECT * FROM pg_locks WHERE NOT granted;
SELECT * FROM pg_stat_activity WHERE state = 'idle in transaction';

-- MySQL - view transactions
SHOW ENGINE INNODB STATUS;
SELECT * FROM information_schema.INNODB_TRX;

-- ===== LONG-RUNNING TRANSACTION DETECTION =====

-- Find transactions running > 30 seconds
SELECT 
    session_id,
    start_time,
    DATEDIFF(second, start_time, GETDATE()) as duration_seconds,
    status
FROM sys.dm_exec_requests
WHERE status = 'running' 
  AND DATEDIFF(second, start_time, GETDATE()) > 30;

-- ===== BEST PRACTICES =====

-- 1. Keep transactions short
BEGIN TRANSACTION;
    -- BAD: User input inside transaction
    -- WAITFOR DELAY '00:01:00'  -- Don't do this!

    -- GOOD: Only actual database operations
    UPDATE accounts SET balance = balance - 100 WHERE id = 1;
    UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

-- 2. Avoid user interaction within transactions
-- BAD
BEGIN TRANSACTION;
    SELECT * FROM products;
    -- Ask user for input here (never do this!)
    UPDATE products SET price = price * 1.1 WHERE id = @user_choice;
COMMIT;

-- 3. Use appropriate isolation level
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;  -- Good default

-- 4. Always handle errors
BEGIN TRY
    BEGIN TRANSACTION;
        -- operations
    COMMIT;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK;
    THROW;
END CATCH

-- 5. Check transaction count before commit
IF @@TRANCOUNT > 0
    COMMIT;
```

**Transaction States:**

```
    Active → Partially Committed → Committed
       ↓              ↓
    Failed → Aborted (Rollback)
```

**Transaction Logging:**

| Database | Log File | Recovery Model |
|----------|----------|----------------|
| SQL Server | .ldf | Full, Simple, Bulk-Logged |
| PostgreSQL | WAL (Write-Ahead Log) | archive, hot_standby |
| MySQL | ib_logfile | InnoDB redo log |
| Oracle | Redo logs | ARCHIVELOG mode |

**Common Transaction Pitfalls:**
1. **Phantom reads** - New rows appearing mid-transaction
2. **Non-repeatable reads** - Data changing between reads
3. **Dirty reads** - Reading uncommitted data
4. **Lost updates** - Overwriting concurrent changes
5. **Deadlocks** - Two transactions waiting on each other
6. **Long-running transactions** - Lock contention, log bloat
